package org.brightstats.data;
import java.util.*;import java.nio.file.*;import com.google.gson.*;import org.brightstats.stats.*;import org.brightstats.data.DataPreparation.*;
/** Preserve missingness semantics across complete-indicator likelihood workflows. */
public final class ExtendedInputChecks {
 static int checks;static void reject(Runnable action){try{action.run();throw new AssertionError("Unsupported input accepted");}catch(IllegalArgumentException|ArithmeticException expected){checks++;}}
 public static void main(String[] args)throws Exception{var model=new LatentInteractionSem.Model(List.of(new LatentInteractionSem.Factor("X",new int[]{0,1,2})),new LatentInteractionSem.Factor("Y",new int[]{3,4,5}),List.of(new LatentInteractionSem.Interaction(0,0)));var names=List.of("X","X2","X3","Y","Y2","Y3","Unused");List<List<String>> rows=new ArrayList<>();for(int i=0;i<40;i++){List<String> row=new ArrayList<>();for(int j=0;j<7;j++)row.add(Double.toString(i+j+.1));rows.add(row);}rows.getFirst().set(6,"");var definitions=names.stream().map(n->new Column(n,Kind.NUMERIC)).toList();var settings=new Settings(',',Decimal.DOT,"",Missing.MEAN_REPLACEMENT);var raw=new Raw(names,rows);var prepared=DataPreparation.prepare(raw,settings,definitions);var history=ImportHistory.capture("Synthetic missingness",raw,settings,definitions);LatentInteractionInput.requireCompleteSelected(history,names,prepared.values(),model);checks++;rows.get(1).set(0,"");var incomplete=new Raw(names,rows);var imputed=DataPreparation.prepare(incomplete,settings,definitions);var missing=ImportHistory.capture("Selected missingness",incomplete,settings,definitions);reject(()->LatentInteractionInput.requireCompleteSelected(missing,names,imputed.values(),model));var remove=new Settings(',',Decimal.DOT,"",Missing.REMOVE_ROWS);var complete=DataPreparation.prepare(incomplete,remove,definitions);LatentInteractionInput.requireCompleteSelected(ImportHistory.capture("Complete cases",incomplete,remove,definitions),names,complete.values(),model);checks++;var json=new Gson().toJsonTree(model).getAsJsonObject();json.addProperty("correlatedErrors",true);reject(()->LatentInteractionInput.model(json));reject(()->LatentInteractionInput.options(JsonParser.parseString("{\"nodes\":9.5}")));reject(()->LatentInteractionInput.options(JsonParser.parseString("{\"nativeLMS\":true}")));var factor=new Gson().toJsonTree(model).getAsJsonObject();factor.getAsJsonArray("predictors").get(0).getAsJsonObject().addProperty("ordinal",true);reject(()->LatentInteractionInput.model(factor));Path out=Path.of(args[0]);Files.createDirectories(out);Files.writeString(out.resolve("input-receipt.json"),"{\"state\":\"passed\",\"checks\":"+checks+"}");System.out.println("Extended input checks: "+checks);}
}
